from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove any spaces from the input string
    groups = []  # Initialize a list to store individual strings

    start = 0
    for i in range(len(paren_string)):
        if paren_string[i] == '(':
            start = i
        elif paren_string[i] == ')':
            groups.append(paren_string[start:i+1])  # Step 2: Identify and extract each group of nested parentheses

    return groups  # Step 3: Separate each group into individual strings and return them as a list

# Test the function
print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']

